class_name Game
extends Node2D
## Paper Land - territory capture on a grid. Smooth 360° movement like Paper.io 2.

signal player_died(killer_name: String)
signal captured(cells: int, is_player: bool)
signal killed_someone(victim: String)
signal rank_changed

const N := 150             # grid size (cells)
const CELL := 10.0         # world pixels per cell
const NONE := 255
const SPEED := 5.2         # cells per second
const TURN_RATE := 9.0     # rad/s smoothing of the heading

const SKINS := [
	{"name": "Blue", "col": Color(0.25, 0.5, 0.95)},
	{"name": "Red", "col": Color(0.93, 0.28, 0.3)},
	{"name": "Green", "col": Color(0.25, 0.75, 0.4)},
	{"name": "Purple", "col": Color(0.6, 0.35, 0.9)},
	{"name": "Orange", "col": Color(0.98, 0.6, 0.15)},
	{"name": "Pink", "col": Color(0.95, 0.4, 0.75)},
	{"name": "Teal", "col": Color(0.15, 0.75, 0.75)},
	{"name": "Yellow", "col": Color(0.95, 0.85, 0.2)},
	{"name": "Black", "col": Color(0.2, 0.2, 0.25)},
	{"name": "Lime", "col": Color(0.6, 0.9, 0.2)},
]
const BOT_NAMES := ["Max", "Zara", "Pixel", "Bolt", "Luna", "Rex", "Kiki", "Nova", "Jax", "Momo", "Ziggy", "Pip"]
const EYES := ["normal", "angry", "happy", "cool", "star"]

var owner_of := PackedByteArray()   # cell -> player id or NONE
var trail_of := PackedByteArray()   # cell -> player id or NONE
var players: Array = []             # Dictionary per player
var counts := PackedInt32Array()
var img: Image
var tex: ImageTexture
var running := false
var player_id := 0
var time_alive := 0.0
var rng := RandomNumberGenerator.new()
var bot_count := 7
var deaths := 0
var kills := 0
var best_pct := 0.0
var font: Font
var font_b: Font
var popups: Array = []              # [pos, text, t, color]
var rank_cache: Array = []
var rank_timer := 0.0
var particles: Array = []           # [pos, vel, t, color]
var sfx_cb: Callable
var player_speed_mult := 1.0

func _ready() -> void:
	rng.randomize()
	texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST

func setup(skin: int, eyes: String, pname: String, bots: int) -> void:
	bot_count = bots
	owner_of.resize(N * N)
	owner_of.fill(NONE)
	trail_of.resize(N * N)
	trail_of.fill(NONE)
	players.clear()
	counts.resize(bots + 1)
	counts.fill(0)
	img = Image.create(N, N, false, Image.FORMAT_RGBA8)
	img.fill(Color(0, 0, 0, 0))
	tex = ImageTexture.create_from_image(img)
	player_id = 0
	_add_player(0, pname, skin, eyes, false)
	var used := [skin]
	var names: Array = BOT_NAMES.duplicate()
	names.shuffle()
	for i in range(bots):
		var s := rng.randi() % SKINS.size()
		while s in used:
			s = rng.randi() % SKINS.size()
		used.append(s)
		_add_player(i + 1, names[i], s, EYES[rng.randi() % EYES.size()], true)
	for p in players:
		_spawn(p)
	_refresh_image_all()
	running = true
	time_alive = 0.0
	deaths = 0
	kills = 0
	popups.clear()
	particles.clear()
	_update_rank()

func _add_player(id: int, nm: String, skin: int, eyes: String, bot: bool) -> void:
	players.append({
		"id": id, "name": nm, "skin": skin, "col": SKINS[skin].col, "eyes": eyes, "bot": bot,
		"pos": Vector2.ZERO, "heading": 0.0, "want": 0.0, "trail": PackedVector2Array(), "trail_cells": PackedInt32Array(),
		"alive": false, "cell": -1, "respawn": 0.0, "ai": {}, "out": false, "wobble": 0.0, "kills": 0, "bb": [0, 0, 0, 0],
	})

func _spawn(p: Dictionary) -> void:
	# find a free spot away from others
	var best := Vector2i(N / 2, N / 2)
	var best_d := -1.0
	for _try in range(40):
		var c := Vector2i(rng.randi_range(8, N - 9), rng.randi_range(8, N - 9))
		var free := true
		for dy in range(-6, 7):
			for dx in range(-6, 7):
				if owner_of[(c.y + dy) * N + c.x + dx] != NONE or trail_of[(c.y + dy) * N + c.x + dx] != NONE:
					free = false
		if not free:
			continue
		var d := 1e9
		for q in players:
			if q.alive and q.id != p.id:
				d = min(d, Vector2(c).distance_to(q.pos))
		if d > best_d:
			best_d = d
			best = c
	p.bb = [best.x, best.y, best.x, best.y]
	for dy in range(-4, 5):
		for dx in range(-4, 5):
			if dx * dx + dy * dy <= 20:
				_set_owner((best.y + dy) * N + best.x + dx, p.id)
	p.pos = Vector2(best) + Vector2(0.5, 0.5)
	p.heading = (Vector2(N * 0.5, N * 0.5) - p.pos).angle() + rng.randf_range(-0.6, 0.6)
	p.want = p.heading
	p.trail = PackedVector2Array()
	p.trail_cells = PackedInt32Array()
	p.alive = true
	p.cell = int(p.pos.y) * N + int(p.pos.x)
	p.out = false
	p.ai = {"phase": 0, "t": 0.0, "turns": 0, "len": rng.randf_range(6.0, 16.0)}
	if p.id == player_id:
		player_speed_mult = 1.0

func _set_owner(i: int, id: int) -> void:
	var prev := owner_of[i]
	if prev != NONE:
		counts[prev] -= 1
	owner_of[i] = id
	if id != NONE:
		counts[id] += 1
		_grow_bb(players[id], i)
	var c := Color(0, 0, 0, 0)
	if id != NONE:
		c = players[id].col
	img.set_pixel(i % N, i / N, c)

func _refresh_image_all() -> void:
	for i in range(N * N):
		var id := owner_of[i]
		img.set_pixel(i % N, i / N, players[id].col if id != NONE else Color(0, 0, 0, 0))
	tex.update(img)

func pct(id: int) -> float:
	return 100.0 * float(counts[id]) / float(N * N)

func player() -> Dictionary:
	return players[player_id]

func set_player_want(angle: float) -> void:
	players[player_id].want = angle

# ---------------------------------------------------------------- update
func _process(dt: float) -> void:
	if not running:
		queue_redraw()
		return
	dt = min(dt, 0.05)
	time_alive += dt
	var dirty := false
	for p in players:
		if not p.alive:
			p.respawn -= dt
			if p.bot and p.respawn <= 0.0:
				_spawn(p)
				dirty = true
			continue
		if p.bot:
			_bot_think(p, dt)
		# turn smoothly toward wanted heading
		var d := wrapf(p.want - p.heading, -PI, PI)
		var maxt := TURN_RATE * dt
		p.heading += clamp(d, -maxt, maxt)
		var spd := SPEED * (player_speed_mult if p.id == player_id else 1.0)
		var step := Vector2(cos(p.heading), sin(p.heading)) * spd * dt
		var np: Vector2 = p.pos + step
		p.wobble += dt * 8.0
		# walls
		if np.x < 0.0 or np.y < 0.0 or np.x >= N or np.y >= N:
			_kill(p, "the wall")
			dirty = true
			continue
		p.pos = np
		var ci := int(np.y) * N + int(np.x)
		if ci != p.cell:
			p.cell = ci
			if _enter_cell(p, ci):
				dirty = true
	if dirty:
		tex.update(img)
	rank_timer -= dt
	if rank_timer <= 0.0:
		rank_timer = 0.5
		_update_rank()
	# popups & particles
	for pp in popups:
		pp[2] -= dt
	popups = popups.filter(func(x): return x[2] > 0.0)
	for pt in particles:
		pt[2] -= dt
		pt[0] += pt[1] * dt
		pt[1] *= 0.92
	particles = particles.filter(func(x): return x[2] > 0.0)
	queue_redraw()

## Returns true if the board image changed.
func _enter_cell(p: Dictionary, ci: int) -> bool:
	var changed := false
	var tr := trail_of[ci]
	if tr != NONE:
		if tr == p.id:
			_kill(p, "your own tail" if p.id == player_id else "its own tail")
			return true
		else:
			# cut someone else's tail
			var victim: Dictionary = players[tr]
			_kill(victim, p.name)
			p.kills += 1
			if p.id == player_id:
				kills += 1
				emit_signal("killed_someone", victim.name)
				_popup(p.pos, "CUT " + victim.name.to_upper() + "!", Color(1, 0.3, 0.3))
			changed = true
	# head-on with another head in the same cell
	for q in players:
		if q.alive and q.id != p.id and q.cell == ci:
			# the one with the longer trail loses; if neither has a trail, nothing happens
			if p.trail_cells.size() > 0 and p.trail_cells.size() >= q.trail_cells.size():
				_kill(p, q.name)
				return true
			elif q.trail_cells.size() > 0:
				_kill(q, p.name)
				if p.id == player_id:
					kills += 1
				changed = true
	if not p.alive:
		return changed
	if owner_of[ci] == p.id:
		if p.trail_cells.size() > 0:
			var got := _capture(p)
			changed = true
			if got > 0:
				emit_signal("captured", got, p.id == player_id)
				if p.id == player_id:
					_popup(p.pos, "+%d" % got, p.col)
		p.out = false
	else:
		p.out = true
		trail_of[ci] = p.id
		p.trail_cells.append(ci)
		_grow_bb(p, ci)
		p.trail.append(p.pos)
	return changed

func _bbox(p: Dictionary) -> Array:
	# bounding box (x0, y0, x1, y1) of my land + trail, padded by 1 and clamped to the map
	var b: Array = p.bb
	return [max(0, b[0] - 1), max(0, b[1] - 1), min(N - 1, b[2] + 1), min(N - 1, b[3] + 1)]

func _grow_bb(p: Dictionary, c: int) -> void:
	var x := c % N
	var y := c / N
	var b: Array = p.bb
	if x < b[0]: b[0] = x
	if y < b[1]: b[1] = y
	if x > b[2]: b[2] = x
	if y > b[3]: b[3] = y

func _capture(p: Dictionary) -> int:
	# Everything not reachable from outside (through cells that are not mine and not my trail) becomes mine.
	# Only the box around my land + trail can be enclosed, so the fill runs on that box only (fast on iPad).
	var bb := _bbox(p)
	var x0: int = bb[0]
	var y0: int = bb[1]
	var x1: int = bb[2]
	var y1: int = bb[3]
	var w := x1 - x0 + 1
	var h := y1 - y0 + 1
	var mark := PackedByteArray()
	mark.resize(w * h)
	mark.fill(0)
	var stack := PackedInt32Array()
	var id: int = p.id
	for lx in range(w):
		for ly in [0, h - 1]:
			var c: int = (y0 + ly) * N + x0 + lx
			if owner_of[c] != id and trail_of[c] != id and mark[ly * w + lx] == 0:
				mark[ly * w + lx] = 1
				stack.append(ly * w + lx)
	for ly in range(h):
		for lx in [0, w - 1]:
			var c: int = (y0 + ly) * N + x0 + lx
			if owner_of[c] != id and trail_of[c] != id and mark[ly * w + lx] == 0:
				mark[ly * w + lx] = 1
				stack.append(ly * w + lx)
	while stack.size() > 0:
		var l := stack[stack.size() - 1]
		stack.resize(stack.size() - 1)
		var lx := l % w
		var ly := l / w
		var c := (y0 + ly) * N + x0 + lx
		if lx > 0 and mark[l - 1] == 0 and owner_of[c - 1] != id and trail_of[c - 1] != id:
			mark[l - 1] = 1
			stack.append(l - 1)
		if lx < w - 1 and mark[l + 1] == 0 and owner_of[c + 1] != id and trail_of[c + 1] != id:
			mark[l + 1] = 1
			stack.append(l + 1)
		if ly > 0 and mark[l - w] == 0 and owner_of[c - N] != id and trail_of[c - N] != id:
			mark[l - w] = 1
			stack.append(l - w)
		if ly < h - 1 and mark[l + w] == 0 and owner_of[c + N] != id and trail_of[c + N] != id:
			mark[l + w] = 1
			stack.append(l + w)
	var got := 0
	for ly in range(h):
		for lx in range(w):
			if mark[ly * w + lx] == 0:
				var c := (y0 + ly) * N + x0 + lx
				if owner_of[c] != id:
					_set_owner(c, id)
					got += 1
	for c in p.trail_cells:
		trail_of[c] = NONE
		if owner_of[c] != id:
			_set_owner(c, id)
			got += 1
	p.trail_cells = PackedInt32Array()
	p.trail = PackedVector2Array()
	# anyone who lost ALL their land dies
	for q in players:
		if q.alive and q.id != p.id and counts[q.id] == 0:
			_kill(q, p.name)
	return got

func _kill(p: Dictionary, by: String) -> void:
	if not p.alive:
		return
	p.alive = false
	p.respawn = rng.randf_range(2.0, 5.0)
	for c in p.trail_cells:
		trail_of[c] = NONE
	p.trail_cells = PackedInt32Array()
	p.trail = PackedVector2Array()
	# their land is freed (only their box needs scanning)
	var bb := _bbox(p)
	for y in range(bb[1], bb[3] + 1):
		for x in range(bb[0], bb[2] + 1):
			var c := y * N + x
			if owner_of[c] == p.id:
				_set_owner(c, NONE)
	for i in range(18):
		var a := rng.randf() * TAU
		particles.append([p.pos, Vector2(cos(a), sin(a)) * rng.randf_range(3.0, 9.0), rng.randf_range(0.5, 1.0), p.col])
	if p.id == player_id:
		deaths += 1
		running = false
		emit_signal("player_died", by)
	elif sfx_cb.is_valid():
		sfx_cb.call("kill_far")

func _popup(pos: Vector2, txt: String, col: Color) -> void:
	popups.append([pos, txt, 1.4, col])

func _update_rank() -> void:
	var arr: Array = []
	for p in players:
		arr.append([counts[p.id], p.name, p.col, p.id, p.alive])
	arr.sort_custom(func(a, b): return a[0] > b[0])
	rank_cache = arr
	emit_signal("rank_changed")

func player_rank() -> int:
	for i in range(rank_cache.size()):
		if rank_cache[i][3] == player_id:
			return i + 1
	return rank_cache.size()

# ---------------------------------------------------------------- bots
func _danger_ahead(p: Dictionary, dist: float, ang: float) -> int:
	# 0 safe, 1 wall, 2 own trail, 3 enemy head close
	var d := Vector2(cos(ang), sin(ang))
	for k in range(1, int(dist) + 1):
		var q: Vector2 = p.pos + d * float(k)
		if q.x < 0.5 or q.y < 0.5 or q.x >= N - 0.5 or q.y >= N - 0.5:
			return 1
		var ci := int(q.y) * N + int(q.x)
		if trail_of[ci] == p.id:
			return 2
	return 0

func _bot_think(p: Dictionary, dt: float) -> void:
	var ai: Dictionary = p.ai
	ai.t -= dt
	var inside: bool = owner_of[p.cell] == p.id
	# 1) opportunistic: an enemy trail cell very close ahead -> go cut it
	if not inside or p.trail_cells.size() == 0:
		for q in players:
			if q.alive and q.id != p.id and q.trail_cells.size() > 3:
				var tc: int = q.trail_cells[q.trail_cells.size() - 1]
				var tp := Vector2(tc % N + 0.5, tc / N + 0.5)
				var dd := tp.distance_to(p.pos)
				if dd < 7.0 and q.pos.distance_to(p.pos) > 3.0:
					var mid: int = q.trail_cells[q.trail_cells.size() / 2]
					var mp := Vector2(mid % N + 0.5, mid / N + 0.5)
					p.want = (mp - p.pos).angle()
					ai.phase = 9
					ai.t = 1.0
					break
	# 2) threat: enemy head near my trail -> head home fast
	if p.trail_cells.size() > 4:
		for q in players:
			if q.alive and q.id != p.id:
				for k in range(0, p.trail_cells.size(), 3):
					var tc2: int = p.trail_cells[k]
					if q.pos.distance_to(Vector2(tc2 % N + 0.5, tc2 / N + 0.5)) < 4.0:
						ai.phase = 3
						break
	if ai.phase == 9 and ai.t > 0.0:
		pass
	elif inside and p.trail_cells.size() == 0:
		# leave territory: pick a heading toward the biggest open area, loop plan
		if ai.phase != 1 or ai.t <= 0.0:
			var best_a: float = p.heading
			var best_s := -1.0
			for i in range(12):
				var a := TAU * float(i) / 12.0
				var free := 0.0
				for k in range(1, 25):
					var q: Vector2 = p.pos + Vector2(cos(a), sin(a)) * float(k)
					if q.x < 1.0 or q.y < 1.0 or q.x >= N - 1 or q.y >= N - 1:
						break
					var ci := int(q.y) * N + int(q.x)
					free += 1.0 if owner_of[ci] == NONE else (0.7 if owner_of[ci] != p.id else 0.1)
				free += rng.randf() * 3.0
				if free > best_s:
					best_s = free
					best_a = a
			p.want = best_a
			ai.phase = 1
			ai.len = rng.randf_range(6.0, 18.0)
			ai.t = ai.len / SPEED
			ai.turns = 0
			ai.turn_dir = 1.0 if rng.randf() < 0.5 else -1.0
	elif ai.phase == 1 or ai.phase == 2:
		# out on a loop: go straight, turn 90°, go, turn 90°, then home
		if ai.t <= 0.0:
			ai.turns += 1
			if ai.turns >= 2:
				ai.phase = 3
			else:
				p.want = p.heading + PI * 0.5 * ai.turn_dir
				ai.t = ai.len / SPEED * rng.randf_range(0.6, 1.2)
				ai.phase = 2
	if ai.phase == 3 and not inside:
		# go home: nearest own cell
		var best: Vector2 = p.pos
		var bd := 1e9
		for k in range(0, p.trail_cells.size(), 2):
			pass
		for y in range(max(0, int(p.pos.y) - 20), min(N, int(p.pos.y) + 21), 2):
			for x in range(max(0, int(p.pos.x) - 20), min(N, int(p.pos.x) + 21), 2):
				if owner_of[y * N + x] == p.id:
					var dd := Vector2(x + 0.5, y + 0.5).distance_squared_to(p.pos)
					if dd < bd:
						bd = dd
						best = Vector2(x + 0.5, y + 0.5)
		if bd < 1e8:
			p.want = (best - p.pos).angle()
		else:
			# no land nearby at all: just keep going and turn
			if ai.t <= 0.0:
				p.want = p.heading + PI * 0.5
				ai.t = 1.5
	elif ai.phase == 3 and inside:
		ai.phase = 0
	# safety: avoid walls / own trail ahead
	var dng := _danger_ahead(p, 4.0, p.want)
	if dng != 0:
		var found := false
		for off in [PI * 0.5, -PI * 0.5, PI * 0.25, -PI * 0.25, PI * 0.75, -PI * 0.75]:
			if _danger_ahead(p, 4.0, p.want + off) == 0:
				p.want = p.want + off
				found = true
				break
		if not found:
			p.want = p.heading + PI

# ---------------------------------------------------------------- drawing
func _draw() -> void:
	if tex == null:
		return
	# board background + grid
	var size := N * CELL
	draw_rect(Rect2(-CELL * 2.0, -CELL * 2.0, size + CELL * 4.0, size + CELL * 4.0), Color(0.72, 0.74, 0.8))
	draw_rect(Rect2(0, 0, size, size), Color(0.96, 0.96, 0.98))
	for i in range(0, N + 1, 5):
		draw_line(Vector2(i * CELL, 0), Vector2(i * CELL, size), Color(0, 0, 0, 0.05), 1.0)
		draw_line(Vector2(0, i * CELL), Vector2(size, i * CELL), Color(0, 0, 0, 0.05), 1.0)
	# territory (texture drawn 1 cell = CELL px); a darker shadow copy offset gives the paper a little depth
	draw_texture_rect(tex, Rect2(0, CELL * 0.5, size, size), false, Color(0, 0, 0, 0.22))
	draw_texture_rect(tex, Rect2(0, 0, size, size), false)
	# trails
	for p in players:
		if not p.alive:
			continue
		if p.trail.size() > 1:
			var pts := PackedVector2Array()
			for v in p.trail:
				pts.append(v * CELL)
			pts.append(p.pos * CELL)
			draw_polyline(pts, Color(p.col, 0.55), CELL * 0.9, true)
		elif p.trail.size() == 1:
			draw_line(p.trail[0] * CELL, p.pos * CELL, Color(p.col, 0.55), CELL * 0.9)
	# heads
	for p in players:
		if not p.alive:
			continue
		_draw_head(p)
	for pt in particles:
		draw_rect(Rect2(pt[0] * CELL - Vector2(3, 3), Vector2(6, 6)), Color(pt[3], clamp(pt[2], 0.0, 1.0)))
	for pp in popups:
		var a: float = clamp(pp[2], 0.0, 1.0)
		var pos: Vector2 = pp[0] * CELL + Vector2(0, -30.0 - (1.4 - pp[2]) * 30.0)
		draw_string(font_b, pos + Vector2(-60, 0), pp[1], HORIZONTAL_ALIGNMENT_CENTER, 120, 18, Color(pp[3], a))

func _draw_head(p: Dictionary) -> void:
	var c: Vector2 = p.pos * CELL
	var s := CELL * 2.6
	var r := Rect2(c - Vector2(s, s) * 0.5, Vector2(s, s))
	draw_rect(Rect2(r.position + Vector2(0, 5), r.size), Color(0, 0, 0, 0.22))
	draw_rect(r, p.col)
	draw_rect(r, Color(1, 1, 1, 0.85), false, 3.0)
	# eyes face the heading
	var d := Vector2(cos(p.heading), sin(p.heading))
	var perp := Vector2(-d.y, d.x)
	var white := Color(1, 1, 1)
	var black := Color(0.1, 0.1, 0.12)
	match p.eyes:
		"happy":
			for sgn in [-1.0, 1.0]:
				var e: Vector2 = c + d * 4.0 + perp * sgn * 6.0
				draw_arc(e, 4.0, PI + 0.3, TAU - 0.3, 8, black, 2.0)
		"cool":
			draw_rect(Rect2(c + d * 3.0 - perp * 7.0 - Vector2(4, 4), Vector2(8, 7)), black)
			draw_line(c + d * 3.0 - perp * 11.0, c + d * 3.0 + perp * 11.0, black, 2.5)
			draw_rect(Rect2(c + d * 3.0 + perp * 7.0 - Vector2(4, 4), Vector2(8, 7)), black)
		"star":
			for sgn in [-1.0, 1.0]:
				var e: Vector2 = c + d * 4.0 + perp * sgn * 6.0
				draw_string(font_b, e + Vector2(-8, 6), "★", HORIZONTAL_ALIGNMENT_CENTER, 16, 15, Color(1, 0.95, 0.3))
		_:
			for sgn in [-1.0, 1.0]:
				var e: Vector2 = c + d * 4.0 + perp * sgn * 6.0
				draw_circle(e, 5.0, white)
				draw_circle(e + d * 2.0, 2.6, black)
				if p.eyes == "angry":
					draw_line(e - perp * sgn * 5.0 + d * 6.0, e + perp * sgn * 5.0 + d * 2.0, black, 2.5)
	# name tag
	if p.id != player_id:
		draw_string(font_b, c + Vector2(-50, -s * 0.5 - 8.0), p.name, HORIZONTAL_ALIGNMENT_CENTER, 100, 14, Color(0.15, 0.15, 0.2, 0.9))
